all.css:
.space {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(45% 55% at 0% 50%, rgba(170, 92, 36, 0.26) 0%, rgba(60, 40, 70, 0.12) 45%, transparent 70%),
    radial-gradient(circle at 65% 42%, rgba(40, 35, 45, 0.5) 0%, rgba(3, 6, 11, 1) 72%),
    #03060b;
}

/* Stars: static haze, no twinkle. Six tiles at different periods so the repeat doesn't read. */
.dust {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    radial-gradient(circle, rgba(255,255,255,0.85) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.60) 0.7px, transparent 1.7px),
    radial-gradient(circle, rgba(200,215,255,0.75) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.50) 0.7px, transparent 1.6px),
    radial-gradient(circle, rgba(255,240,220,0.65) 0.9px, transparent 2px),
    radial-gradient(circle, rgba(255,255,255,0.55) 0.7px, transparent 1.7px);
  background-position: 29px 47px, 213px 288px, 388px 129px, 97px 401px, 472px 334px, 266px 533px;
  background-size: 590px 590px, 523px 523px, 671px 671px, 487px 487px, 733px 733px, 611px 611px;
  opacity: 0.6;
}

/* Centred on the left edge, so the visible half runs core to limb. */
.sun {
  position: absolute;
  left: -20vmin;
  top: 50%;
  width: 40vmin;
  height: 40vmin;
  margin-top: -20vmin;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 50%,
      #ffeec4 0%,
      #ffd894 24%,
      #f5a94b 46%,
      #d97a28 66%,
      #a44c16 84%,
      #602008 100%);
  box-shadow: 0 0 7vmin rgba(255, 150, 60, 0.32);
}

/* Lit from the left, where the sun is. Kept shallow: a heavy inset over a small circle eats the
   colour and everything reads grey. */
.planet {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: var(--s);
  height: var(--s);
  margin-left: calc(var(--s) / -2);
  margin-top: calc(var(--s) / -2);
  border-radius: 50%;
  box-shadow:
    inset calc(var(--s) * -0.2) 0 calc(var(--s) * 0.26) rgba(0, 0, 0, 0.45),
    0 0 calc(var(--s) * 0.5) rgba(255, 190, 130, 0.18);
}

.mercury { background: linear-gradient(125deg, #cbbfae, #6b6157); }
.venus   { background: linear-gradient(125deg, #ffe9a8, #c98a3a); }
.earth   { background: linear-gradient(125deg, #6fd0e8, #1f5fa8); }
.mars    { background: linear-gradient(125deg, #ff9a5e, #a83a1c); }
.jupiter { background: linear-gradient(125deg, #f2d3a4, #a2673a); }
.uranus  { background: linear-gradient(125deg, #b8f4ee, #4f9fb4); }
.neptune { background: linear-gradient(125deg, #8fb4ff, #2a44a8); }

.jupiter {
  background:
    repeating-linear-gradient(
      180deg,
      rgba(0, 0, 0, 0.18) 0 3%,
      rgba(255, 255, 255, 0.12) 3% 6%,
      rgba(0, 0, 0, 0.07) 6% 10%,
      rgba(255, 214, 168, 0.14) 10% 13%
    ),
    radial-gradient(circle at 33% 40%, #fbe8ca, #d3a370 50%, #91603a 74%, #442816);
}

.saturn {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: var(--s);
  height: var(--s);
  margin-left: calc(var(--s) / -2);
  margin-top: calc(var(--s) / -2);
}
.saturn .body {
  --x: 50%;
  --y: 50%;
  background: linear-gradient(125deg, #ffeec4, #b8873f);
}
/* The ring is drawn twice, clipped to a half eacder the planet, the
   front half over it. The clip is on the wrapper so the cut stays horizontal while the ring inside
   it carries the tilt. */
.saturn .ringHalf {
  position: absolute;
  inset: 0;
}
.saturn .back  { clip-path: inset(0 0 50% 0); }
.saturn .front { clip-path: inset(50% 0 0 0); }

.saturn .ring {
  position: absolute;
  left: 50%;
  top: 50%;
  width: calc(var(--s) * 2.35);
  height: calc(var(--s) * 2.35);
  margin-left: calc(var(--s) * -1.175);
  margin-top: calc(var(--s) * -1.175);
  border-radius: 50%;
  transform: rotate(-16deg) rotateX(76deg);
  border: calc(var(--s) * 0.1) solid rgba(240, 22
  box-shadow:
    0 0 0 calc(var(--s) * 0.05) rgba(226, 205, 16
    inset 0 0 0 calc(var(--s) * 0.055) rgba(170, 148, 116, 0.45);
}

.earth .moon {
  position: absolute;
  left: 155%;
  top: 4%;
  width: 26%;
  height: 26%;
  border-radius: 50%;
  background: radial-gradient(circle at 34% 36%, );
  box-shadow: inset -1px 0 2px rgba(0, 0, 0, 0.8);
}

/* Asteroid belt: a tilted band of scattered dots between Mars and Jupiter, faded out at both ends. */
.belt {
  position: absolute;
  left: 58%;
  top: 48%;
  width: 30vmin;
  height: 82vmin;
  margin-left: -15vmin;
  margin-top: -41vmin;
  transform: rotate(-13deg);
  pointer-events: none;
  background-image:
    radial-gradient(circle, rgba(226, 212, 188, 0.95) 1.1px, transparent 2.4px),
    radial-gradient(circle, rgba(190, 176, 154, 0),
    radial-gradient(circle, rgba(255, 240, 214, 0.70) 1.4px, transparent 3px),
    radial-gradient(circle, rgba(160, 148, 130, 0.65) 0.8px, transparent 1.8px);
  background-position: 3px 11px, 41px 66px, 77px
  background-size: 97px 131px, 71px 89px, 149px 113px, 61px 103px;
  mask-image: radial-gradient(ellipse 50% 48% at t 100%);
  opacity: 0.85;
}
